import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { updateTaxLinesWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await updateTaxLinesWorkflow(req.scope)
    .run({
      input: {
        cart_id: "cart_123",
      }
    })

  res.send(result)
}

